select mo.order_id as orderId, mo.order_no as orderNo, mo.account_id as accountId, a.nick_name as accountNickName, a.mobile as accountMobile, mo.order_status as orderStatus, mo.total_amount as totalAmount, mo.discount_amount as discountAmount, mo.coupon_id as couponId, mo.coupon_name as couponName, mo.coupon_threshold_amount as couponThresholdAmount, mo.coupon_discount_amount as couponDiscountAmount, mo.coupon_amount as couponAmount, mo.freight_amount as freightAmount, mo.pay_amount as payAmount, mo.account_coupon_id as accountCouponId, mo.receiver_name as receiverName, mo.receiver_phone as receiverPhone, mo.receiver_address as receiverAddress, mo.buyer_remark as buyerRemark, mo.cancel_reason as cancelReason, mo.delivery_time as deliveryTime, mo.receive_time as receiveTime, mo.finish_time as finishTime, mo.payment_no as paymentNo, mo.pay_type as payType, mo.pay_status as payStatus, mo.transaction_no as transactionNo, mo.pay_time as payTime, mo.refund_amount as refundAmount, mo.refund_status as refundStatus, mo.refund_count as refundCount, mo.del_flag as delFlag, mo.create_time as createTime, mo.update_time as updateTime, mo.remark as remark from mall_order mo left join account a on mo.account_id = a.account_id and a.del_flag = 0 where mo.del_flag = 0
and mo.order_no like concat('%', #{orderNo}, '%')
and mo.account_id = #{accountId}
and a.nick_name like concat('%', #{accountNickName}, '%')
and a.mobile like concat('%', #{accountMobile}, '%')
and mo.order_status = #{orderStatus}
and mo.coupon_id = #{couponId}
and mo.account_coupon_id = #{accountCouponId}
and mo.coupon_name like concat('%', #{couponName}, '%')
and mo.receiver_name like concat('%', #{receiverName}, '%')
and mo.receiver_phone like concat('%', #{receiverPhone}, '%')
and mo.pay_type = #{payType}
and mo.pay_status = #{payStatus}
and mo.refund_status = #{refundStatus}
order by mo.order_id desc

